    draw, resize, setCourse, island, snapCamera,
    toggleCamera() { cameraMode = cameraMode === CAMERA_CHASE ? CAMERA_COCKPIT : CAMERA_CHASE; return cameraMode; },
    cameraMode() { return cameraMode; },
    setCameraMode(mode) { cameraMode = mode; },
  };
}
